export const pmsReceptionTranslations: Record<string, Record<string, string>> = Object.fromEntries(
  LANGS.map((lang, index) => [
    lang,
    Object.fromEntries(Object.entries({ ...rows, ...partialRows } as Record<string, readonly string[]>).map(([key, values]) => [key, values[index] ?? values[0]])),
  ]),
);

for (const lang of LANGS) {
  pmsTranslations[lang] = {
    ...(pmsTranslations[lang] ?? {}),
    ...pmsReceptionTranslations[lang],
  };
}
